parameters.jsCode:
const rawOutput = $json.output;

if (!rawOutput) {
  throw new Error('Company Research Agent returned no output.');
}

let result;

try {
  result = typeof rawOutput === 'string'
    ? JSON.parse(rawOutput)
    : rawOutput;
} catch (error) {
  throw new Error(
    'Company Research Agent returned invalid JSON: ' + error.message
  );
}

return {
  json: {
    // =========================
    // LEAD INFORMATION
    // =========================
    name: result.lead?.name || "",
    email: result.lead?.email || "",
    company: result.lead?.company || "",
    website: result.lead?.website || "",
    industry: result.lead?.industry || "",
    service: result.lead?.service || "",
    budget: result.lead?.budget || "",
    message: result.lead?.message || "",
    source: result.lead?.source || "",
    submitted_at: result.lead?.submitted_at || "",

    // =========================
    // AI QUALIFICATION
    // =========================
    lead_score: Number(result.qualification?.lead_score) || 0,
    priority: result.qualification?.priority || "",
    intent: result.qualification?.intent || "",
    reason: result.qualification?.reason || "",
    recommended_action: result.qualification?.recommended_action || "",

    // =========================
    // COMPANY RESEARCH
    // =========================
    company_summary: result.company_research?.company_summary || "",
    researched_industry: result.company_research?.industry || "",
    business_model: result.company_research?.business_model || "",

    pain_points: Array.isArray(result.company_research?.pain_points)
      ? result.company_research.pain_points
      : [],

    automation_opportunities: Array.isArray(
      result.company_research?.automation_opportunities
    )
      ? result.company_research.automation_opportunities
      : [],

    recommended_service:
      result.company_research?.recommended_service || "",

    sales_angle:
      result.company_research?.sales_angle || ""
  }
};

